const summary = $input.first().json;
if (!summary.totalNewProperties || summary.totalNewProperties === 0) {
  return [];
}

const topZones = (summary.zones || []).slice(0, 5);
const lines = topZones.map((z) => {
  const verifiedCount = z.items.filter((i) => i.isVerified).length;
  const featuredCount = z.items.filter((i) => i.isFeatured).length;
  const badges = [];
  if (featuredCount > 0) badges.push(`⭐ ${featuredCount} destacado(s)`);
  if (verifiedCount > 0) badges.push(`✅ ${verifiedCount} verificado(s)`);
  const extra = badges.length > 0 ? ` (${badges.join(', ')})` : '';
  return `📍 ${z.zone}, ${z.city}: ${z.count} inmueble(s) nuevo(s)${extra}`;
});

const message =
  `🏘️ ¡Resumen semanal! Esta semana se sumaron ${summary.totalNewProperties} inmuebles nuevos al mapa:\n\n` +
  lines.join('\n') +
  `\n\nExplora todos los pines disponibles en nuestra plataforma.`;

const pageId = $env.META_PAGE_ID;
const accessToken = $env.META_PAGE_ACCESS_TOKEN;

if (pageId && accessToken) {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://graph.facebook.com/v21.0/${pageId}/feed`,
    body: {
      message,
      access_token: accessToken,
    },
    json: true,
  });
  return [{ json: { published: true, fb_post_id: res.id, message } }];
}

return [{ json: { published: false, reason: 'META credentials empty', message } }];
